(function(root){
const MAX=10*1024*1024,allowed=['application/pdf','image/jpeg','image/png','image/webp'];let dbPromise;
function db(){return dbPromise||=new Promise((resolve,reject)=>{const r=indexedDB.open('bevy-expense-proof',1);r.onupgradeneeded=()=>r.result.createObjectStore('files',{keyPath:'key'});r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(Error('Attachment storage unavailable. Enable browser storage before submitting.'));});}
async function validate(file){if(!file||!file.size)throw Error('Attach a bill or invoice (PDF, JPG, PNG or WebP).');if(file.size>MAX)throw Error('Attachment must be 10 MB or smaller.');if(!allowed.includes(file.type))throw Error('Use a PDF, JPG, PNG or WebP bill.');const bytes=new Uint8Array(await file.slice(0,12).arrayBuffer());const signature=file.type==='application/pdf'?new TextDecoder().decode(bytes).startsWith('%PDF-'):file.type==='image/png'?bytes[0]===137&&bytes[1]===80&&bytes[2]===78&&bytes[3]===71:file.type==='image/jpeg'?bytes[0]===255&&bytes[1]===216&&bytes[2]===255:new TextDecoder().decode(bytes.slice(0,4))==='RIFF'&&new TextDecoder().decode(bytes.slice(8,12))==='WEBP';if(!signature)throw Error('The file content does not match its PDF/image type.');return file;}
async function put(file){await validate(file);const hash=[...new Uint8Array(await crypto.subtle.digest('SHA-256',await file.arrayBuffer()))].map(n=>n.toString(16).padStart(2,'0')).join('');const rec={key:crypto.randomUUID(),name:file.name,type:file.type,size:file.size,hash,blob:file};const d=await db();await new Promise((resolve,reject)=>{const tx=d.transaction('files','readwrite');tx.objectStore('files').put(rec);tx.oncomplete=resolve;tx.onabort=tx.onerror=()=>reject(Error('Could not save attachment; claim was not submitted.'));});return {receipt:rec.name,receiptKey:rec.key,receiptHash:hash,receiptType:rec.type,receiptSize:rec.size};}
async function get(key){if(key?.startsWith('builtin:')){const blob=await (await fetch('demo-receipt.pdf')).blob();return {blob,type:'application/pdf',name:'Fictional sample bill.pdf'};}const d=await db();return new Promise((resolve,reject)=>{const r=d.transaction('files').objectStore('files').get(key);r.onsuccess=()=>resolve(r.result);r.onerror=reject;});}
async function sample(c){const canvas=document.createElement('canvas');canvas.width=1000;canvas.height=1250;const x=canvas.getContext('2d');x.fillStyle='#fff';x.fillRect(0,0,1000,1250);x.fillStyle='#17654e';x.font='bold 44px sans-serif';x.fillText('Bevy Commerce • DEMO BILL',70,100);x.fillStyle='#24382d';x.font='26px sans-serif';const lines=['FICTIONAL EVIDENCE — NOT A REAL RECEIPT',c.vendor||'Demo vendor',c.invoice||'Demo reference '+crypto.randomUUID(),c.date||'',c.category||'',(c.currency||'BDT')+' '+Number(c.amount||0).toFixed(2),c.purpose||'Work expense'];lines.forEach((line,i)=>x.fillText(line.slice(0,65),70,210+i*90));const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/png'));return new File([blob],'demo-bill-'+(c.invoice||Date.now())+'.png',{type:'image/png'});}
root.ExpenseReceipts={put,get,sample,validate,MAX};
})(globalThis);
